function applyRenderEntities(input){const list=Array.isArray(input)?input:Array.isArray(input?.entities)?input.entities:[];const wanted=new Set();for(const e of list){const id=String(e?.id||'');if(!id)continue;wanted.add(id);const sig=JSON.stringify(e),record=renderedEntities.get(id);if(record?.signature===sig)continue;if(record?.object?.userData?.creature&&e.animalId&&String(e.part||'')==='creature'){const u=record.object.userData;u.target.set(Number(e.x||0),0,Number(e.z||0));u.headingTarget=-Number(e.heading||0);u.behavior=String(e.behavior||'roaming');u.kind=String(e.kind||u.kind||'herbivore');record.signature=sig;continue}renderPersistentEntity(e)}for(const id of [...renderedEntities.keys()])if(!wanted.has(id))removeRenderedEntity(id)}

function playerColor(id){let h=0;for(const c of String(id))h=(h*31+c.charCodeAt(0))>>>0;return new THREE.Color().setHSL((h%360)/360,.42,.55)}
function makeNameSprite(name){const canvas=document.createElement('canvas');canvas.width=256;canvas.height=64;const c=canvas.getContext('2d');c.clearRect(0,0,256,64);c.font='600 28px system-ui';c.textAlign='center';c.textBaseline='middle';c.fillStyle='rgba(10,16,12,.72)';c.fillRect(18,10,220,44);c.fillStyle='#f6f1df';c.fillText(String(name||'Traveler').slice(0,20),128,32);const tex=new THREE.CanvasTexture(canvas);tex.colorSpace=THREE.SRGBColorSpace;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthWrite:false}));s.position.set(0,2.65,0);s.scale.set(3.2,.8,1);return s}
function createRemotePlayer(row){const g=createHumanoid({outfit:playerColor(row.client_id),pack:true});g.add(makeNameSprite(row.display_name));const x=Number(row.x||0),z=Number(row.z||12);g.position.set(x,0,z);scene.add(g);return{object:g,target:new THREE.Vector3(x,0,z),lastTarget:new THREE.Vector3(x,0,z),lastSeen:Date.now(),moving:false}}
function removeRemotePlayer(id){const p=remotePlayers.get(id);if(!p)return;scene.remove(p.object);p.object.traverse(o=>{o.geometry?.dispose?.();if(Array.isArray(o.material))o.material.forEach(m=>{m.map?.dispose?.();m.dispose?.()});else{ o.material?.map?.dispose?.();o.material?.dispose?.();}});remotePlayers.delete(id)}
function applyRemotePlayers(rows=[]){const self=localStorage.getItem(CLIENT_KEY)||'';const now=Date.now(),seen=new Set();let activeCount=self?1:0;for(const row of rows){const id=String(row.client_id||'');if(!id||id===self)continue;const stamp=Date.parse(row.last_seen_at||'');if(Number.isFinite(stamp)&&now-stamp>10000)continue;const x=Number(row.x),z=Number(row.z);if(!Number.isFinite(x)||!Number.isFinite(z))continue;activeCount++;seen.add(id);let p=remotePlayers.get(id);if(!p){p=createRemotePlayer(row);remotePlayers.set(id,p)}p.lastTarget.copy(p.target);p.target.set(x,0,z);p.lastSeen=now;p.moving=p.target.distanceToSquared(p.lastTarget)>.0025;}for(const [id,p] of remotePlayers){if(!seen.has(id)&&now-p.lastSeen>10000)removeRemotePlayer(id)}if(onlineEl)onlineEl.textContent=`${Math.max(activeCount,1)} traveler${activeCount===1?'':'s'}`}
function nearestPlantForCreature(g,maxDistance=11){let best=null,bestD=maxDistance;for(const plant of resourceNodes){if(plant.resource!=='herbs'||plant.depleted||!plant.object?.visible)continue;const d=g.position.distanceTo(plant.object.position);if(d<bestD){best=plant;bestD=d}}return best}
function updateHerbivoreFeeding(g,u,t){if(u.kind!=='herbivore')return;u.hunger=Number.isFinite(u.hunger)?u.hunger:35;u.hunger=Math.min(100,u.hunger+.003);const plant=nearestPlantForCreature(g);if(!plant)return;if(u.hunger>=28||u.feedingPlant){u.feedingPlant=plant;u.target=plant.object.position.clone();const d=g.position.distanceTo(plant.object.position);if(d<1.25){u.behavior='feeding';if(!u.nextBiteAt||t>=u.nextBiteAt){u.nextBiteAt=t+5000;u.hunger=Math.max(0,u.hunger-18);plant.grazedVisual=Math.min(.55,(plant.grazedVisual||0)+.08);plant.object.scale.y=Math.max(.45,1-plant.grazedVisual);showToast(`${u.species||u.kind||'Herbivore'} grazes on ${plant.label}.`);recordEcologyEvent('ecology_grazing',{species:u.species||'herbivore',plant:plant.label,nodeId:plant.nodeId,amount:1,x:Number(g.position.x.toFixed(2)),z:Number(g.position.z.toFixed(2))})}if(u.hunger<15){u.feedingPlant=null;u.behavior='roaming';u.target.set(g.position.x+(Math.random()-.5)*8,0,g.position.z+(Math.random()-.5)*8)}}else u.behavior='seeking food'}}
function livingCreatures(){const out=[];for(const record of renderedEntities.values()){const g=record.object,u=g?.userData;if(g&&u?.creature&&!u.dead)out.push({g,u})}return out}
function nearestPreyForCreature(g,maxDistance=16){let best=null,bestD=maxDistance;for(const c of livingCreatures()){if(c.g===g||c.u.kind==='predator')continue;const d=g.position.distanceTo(c.g.position);if(d<bestD){best=c;bestD=d}}return best}
async function recordEcologyEvent(type,payload={}){const clientId=localStorage.getItem(CLIENT_KEY);if(!clientId)return;try{await fetch(WORLD_API,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({clientId,name:playerName,x:Number(player.position.x.toFixed(3)),z:Number(player.position.z.toFixed(3)),event:{type,payload}})})}catch{}}
function updatePredatorFeeding(g,u,t){if(u.kind!=='predator')return;u.hunger=Number.isFinite(u.hunger)?u.hunger:32;u.hunger=Math.min(100,u.hunger+.0025);if(u.hunger<30&&!u.preyTarget)return;const prey=u.preyTarget&&!u.preyTarget.u.dead?u.preyTarget:nearestPreyForCreature(g);if(!prey){u.behavior='roaming';u.preyTarget=null;return}u.preyTarget=prey;u.target=prey.g.position.clone();const d=g.position.distanceTo(prey.g.position);if(d<1.15){u.behavior='feeding';if(!u.nextBiteAt||t>=u.nextBiteAt){u.nextBiteAt=t+6500;prey.u.health=Number.isFinite(prey.u.health)?prey.u.health:100;prey.u.health-=55;if(prey.u.health<=0){prey.u.dead=true;prey.g.visible=false;u.hunger=Math.max(0,u.hunger-55);showToast(`${u.species||'Predator'} caught ${prey.u.species||'prey'}.`);recordEcologyEvent('ecology_predation',{predator:u.species||'predator',prey:prey.u.species||'herbivore',x:Number(g.position.x.toFixed(2)),z:Number(g.position.z.toFixed(2))});u.preyTarget=null;u.behavior='feeding';u.nextMealEnd=t+3500}else{prey.u.behavior='fleeing';prey.u.target.set(prey.g.position.x+(prey.g.position.x-g.position.x)*5,0,prey.g.position.z+(prey.g.position.z-g.position.z)*5)}}}else u.behavior='stalking'}
function updateFoodWebBehavior(g,u,t){if(u.creature)return;updateHerbivoreFeeding(g,u,t);updatePredatorFeeding(g,u,t);if(u.kind!=='predator'&&u.kind!=='herbivore'){u.hunger=Number.isFinite(u.hunger)?u.hunger:20;u.hunger=Math.min(100,u.hunger+.0015)}}
function updateCreatures(t,dt){for(const record of renderedEntities.values()){const g=record.object,u=g?.userData;if(!u?.creature||!u.target)continue;updateFoodWebBehavior(g,u,t);let tx=u.target.x,tz=u.target.z,behavior=u.behavior||'roaming';const px=g.position.x-player.position.x,pz=g.position.z-player.position.z,pdist=Math.hypot(px,pz);if(u.kind!=='predator'&&pdist<6.5){const inv=1/Math.max(.001,pdist),push=Math.min(4,1+(6.5-pdist)*.75);tx=g.position.x+px*inv*push;tz=g.position.z+pz*inv*push;behavior='fleeing'}const dx=tx-g.position.x,dz=tz-g.position.z,dist=Math.hypot(dx,dz);let moving=dist>.025;if(behavior==='feeding')moving=false;const pace=behavior==='fleeing'?7:behavior==='stalking'?3.8:behavior==='feeding'?1.2:2.7;if(moving){const a=1-Math.exp(-pace*dt);g.position.x+=dx*a;g.position.z+=dz*a;const desiredHeading=-Math.atan2(dz,dx);let turn=((desiredHeading-g.rotation.y+Math.PI)%(Math.PI*2))-Math.PI;g.rotation.y+=turn*Math.min(1,dt*(behavior==='fleeing'?9:5))}else if(u.kind==='predator'&&pdist<8){const desiredHeading=-Math.atan2(player.position.z-g.position.z,player.position.x-g.position.x);let turn=((desiredHeading-g.rotation.y+Math.PI)%(Math.PI*2))-Math.PI;g.rotation.y+=turn*Math.min(1,dt*2.5)}const r=u.rig;if(!r)continue;const gait=moving?Math.sin(t*(behavior==='fleeing' ? .016 : .009))*(behavior==='fleeing' ? .55 : .32):0;if(r.legs?.length===4){r.legs[0].rotation.z=gait;r.legs[1].rotation.z=-gait;r.legs[2].rotation.z=-gait;r.legs[3].rotation.z=gait}if(r.body)r.body.position.y=r.bodyBaseY+(moving?Math.abs(Math.sin(t*.012))*.035:0);if(r.head){const feeding=behavior==='feeding';r.head.position.y=r.headBaseY+(feeding?-.16+.04*Math.sin(t*.004):(moving ? .025*Math.sin(t*.007) : 0));r.head.rotation.z=feeding?-.38+.08*Math.sin(t*.004):0}if(r.tail)r.tail.rotation.x=(behavior==='fleeing' ? .18 : .06)*Math.sin(t*.011)}}
function updateRemotePlayers(dt,t){const alpha=1-Math.exp(-8*Math.max(0,dt));for(const p of remotePlayers.values()){const dx=p.target.x-p.object.position.x,dz=p.target.z-p.object.position.z;if(Math.hypot(dx,dz)>.015)p.object.rotation.y=Math.atan2(dx,dz);p.object.position.lerp(p.target,alpha);animateHumanoid(p.object,p.moving,t,1)}}

